# brute force partitions of an object into 2x2 squares and L-trominoes
def partitions(obj):
    obj=frozenset(obj); res=[]
    def rec(rem, acc):
        if not rem: res.append(list(acc)); return
        p=min(rem)
        # square top-left at p
        sq={(p[0],p[1]),(p[0],p[1]+1),(p[0]+1,p[1]),(p[0]+1,p[1]+1)}
        if sq<=rem: rec(rem-sq, acc+[('S',sq)])
        # L boxes containing p: p as each corner
        for dr in (0,-1):
            for dc in (0,-1):
                box={(p[0]+dr+a,p[1]+dc+b) for a in (0,1) for b in (0,1)}
                if box<=obj:
                    for miss in list(box-{p}):
                        # L must include p; missing corner != p
                        pass
                # L = box minus one corner, must include p, and not be full square
                if box<=obj:
                    for miss in box:
                        if miss==p: continue
                        L=box-{miss}
                        if p in L and L<=rem:
                            rec(rem-L, acc+[('L'+str(tuple(sorted(box-{miss}-((p,)) if False else []))) if False else ('L',frozenset(L),frozenset(miss and box or box)),L)])
        return
    rec(obj,[])
    return res

