def tile_squares_and_els(grid, square_color=1, corner_colors=None):
    """Recolor each 8-style object (any nonzero color) after tiling it (uniquely, greedy top-left)
    with 2x2 squares and L-trominoes: squares -> square_color, each L -> color of its missing corner
    (NW, SW, NE, SE -> 2, 3, 4, 5 by default)."""
    if corner_colors is None: corner_colors = {(0,0):2,(1,0):3,(0,1):4,(1,1):5}
    H,W=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    seen=set()
    for r in range(H):
        for c in range(W):
            if grid[r][c] and (r,c) not in seen:
                col=grid[r][c]
                obj={(rr,cc) for rr in range(H) for cc in range(W) if grid[rr][cc]==col}
                seen|=obj
                def rec(rem, acc):
                    if not rem: return acc
                    p=min(rem)
                    sq={(p[0],p[1]),(p[0],p[1]+1),(p[0]+1,p[1]),(p[0]+1,p[1]+1)}
